/** MVP227 — adaptador PRIVADO del RPC al seguimiento del comprador.
 * Sin proveedor/telefono/source HMAC, sin ranking global ni adjudicación.
 * Solo precios con verificación de origen que SQL autorizó por token.
 */
import {RUBROS_MVP216,type RubroMvp216} from '../rubros-comprador-mvp216.ts';
export type SalidaVistaMvp227=Readonly<{
 received_count:number;files_pending_review:number;
 offers:readonly Readonly<{label:string;text:string}>[];
 rubros_ia:readonly Readonly<{
  rubro:RubroMvp216;titulo:string;
  solicitados:number;ofertas:number
 }>[];
}>;
const obj=(v:unknown):v is Record<string,unknown>=>
 v!==null&&typeof v==='object'&&!Array.isArray(v);
const itemId=/^item_[1-9][0-9]{0,2}$/u;
const safe=(v:unknown,max:number):v is string=>
 typeof v==='string'&&v.trim().length>0&&v.length<=max&&
 !/[\u0000-\u001f\u007f]/u.test(v);
const amt=/^[0-9]{1,17}$/u;
function displayCentavos(amount:string,moneda:'ARS'|'USD'):string{
 const cents=BigInt(amount);
 const integer=(cents/100n).toString().replace(/\B(?=(\d{3})+(?!\d))/gu,'.');
 const fraction=(cents%100n).toString().padStart(2,'0');
 return (moneda==='ARS'?'$ ':'USD ')+integer+','+fraction;
}
export function vistaCotizacionesRubrosMvp227(input:unknown):
 SalidaVistaMvp227|null{
 if(!obj(input)||input.state!=='rubros_por_articulo'||
    !Array.isArray(input.items)||input.items.length<1||
    input.items.length>200||
    !Array.isArray(input.ofertas)||input.ofertas.length>25||
    typeof input.recibidos!=='number'||
    (typeof input.recibidos!=='number'||typeof input.recibidos!=='number'||!Number.isSafeInteger(input.recibidos))||
    (input.recibidos as number)<0||
    (input.recibidos as number)>25||
    typeof input.pendientes_revision!=='number'||
    (typeof input.pendientes_revision!=='number'||
      typeof input.pendientes_revision!=='number'||!Number.isSafeInteger(input.pendientes_revision))||
    (input.pendientes_revision as number)<0||
    (input.pendientes_revision as number)>100)
   return null;
 const seen=new Set<string>();
 const items=new Map<string,Readonly<{
  descripcion:string;rubro:RubroMvp216;cantidad:string;unidad:string
 }>>();
 for(const x of input.items){
  if(!obj(x)||typeof x.itemId!=='string'||!itemId.test(x.itemId)||
     seen.has(x.itemId)||!safe(x.descripcion,500)||
     !safe(x.cantidad,40)||!/^\d{1,8}(?:\.\d{1,3})?$/u.test(x.cantidad)||
     !safe(x.unidad,20)||
     !['unit','bag','box','kg','g','l','ml','m','m2','m3','roll','pack'].includes(x.unidad)||
     typeof x.rubro!=='string'||!Object.hasOwn(RUBROS_MVP216,x.rubro))
   return null;
  seen.add(x.itemId);
  items.set(x.itemId,{descripcion:x.descripcion,rubro:x.rubro as RubroMvp216,
   cantidad:x.cantidad,unidad:x.unidad});
 }
 const offers:SalidaVistaMvp227['offers'][number][]=[];
 const labels=new Set<string>();
 const byRubro=new Map<RubroMvp216,number>();
 for(const offer of input.ofertas){
  if(!obj(offer)||typeof offer.label!=='string'||
     !/^Presupuesto [1-9][0-9]{0,2}$/u.test(offer.label)||
     labels.has(offer.label)||!['ARS','USD'].includes(String(offer.moneda))||
     !['incluido_explicito','sin_iva_explicito','no_informado'].includes(String(offer.iva))||
     !['incluido_explicito','excluido_explicito','a_convenir','no_informado'].includes(String(offer.flete))||
     !['contado','transferencia','credito','no_informado'].includes(String(offer.pago))||
     !Array.isArray(offer.rubros)||offer.rubros.length>7||
     !Array.isArray(offer.precios)||offer.precios.length>25)return null;
  labels.add(offer.label);
  const price=new Map<string,string>();
  const quotedRubros=new Set<string>();
  for(const line of offer.precios){
   if(!obj(line)||typeof line.pedidoId!=='string'||
      !items.has(line.pedidoId)||price.has(line.pedidoId)||
      typeof line.centavos!=='string'||!amt.test(line.centavos))
    return null;
   price.set(line.pedidoId,line.centavos);
  }
  for(const r of offer.rubros){
   if(!obj(r)||typeof r.rubro!=='string'||
      !Object.hasOwn(RUBROS_MVP216,r.rubro)||
      typeof r.solicitados!=='number'||typeof r.respondidos!=='number'||
      typeof r.solicitados!=='number'||typeof r.solicitados!=='number'||!Number.isSafeInteger(r.solicitados)||
      typeof r.respondidos!=='number'||typeof r.respondidos!=='number'||!Number.isSafeInteger(r.respondidos)||
      (r.solicitados as number)<1||(r.respondidos as number)<0||
      (r.respondidos as number)>(r.solicitados as number)||
      !['completa','parcial','sin_cobertura'].includes(String(r.cobertura)))
    return null;
   const rubro=r.rubro as RubroMvp216;
   const nSolicitados=r.solicitados as number;
   const nRespondidos=r.respondidos as number;
   if(quotedRubros.has(rubro))return null;
   quotedRubros.add(rubro);
   byRubro.set(rubro,(byRubro.get(rubro)??0)+1);
   const corresponding=[...items].filter(([,v])=>v.rubro===rubro);
   // La lista general del comprador puede contener MÁS artículos que
   // los asignados a este negocio. Nunca inventar cobertura total.
   if(nSolicitados>corresponding.length)return null;
   if(nRespondidos>corresponding.length)return null;
   const details=corresponding.map(([id,v])=>
    v.descripcion+' ('+v.cantidad+' '+v.unidad+'): '+
    (price.has(id)?displayCentavos(price.get(id)!,offer.moneda as 'ARS'|'USD'):
      'Sin precio directamente comparable')).join('\n');
   const iva=offer.iva==='incluido_explicito'?'IVA incluido explícito':
    offer.iva==='sin_iva_explicito'?'Sin IVA explícito':'IVA no informado';
   const flete=offer.flete==='incluido_explicito'?'Flete incluido':
    offer.flete==='excluido_explicito'?'Flete no incluido':
    offer.flete==='a_convenir'?'Flete a convenir':'Flete no informado';
   offers.push({label:offer.label+' · '+RUBROS_MVP216[rubro],
    text:'Cotizó '+nRespondidos+' de '+nSolicitados+
     ' artículos asignados a este negocio ('+corresponding.length+
     ' solicitados en el rubro completo).\n'+
     details+'\n'+iva+' · '+flete+
     ' · Pago: '+offer.pago+'. Sin adjudicación automática.'});
  }
  // Una línea de precio no puede aparecer en un rubro que el negocio
  // no cotizó ni está acreditado por el reporte de la misma fuente.
  if([...price.keys()].some(id=>!quotedRubros.has(items.get(id)!.rubro)))
    return null;
 }
 const rubros=[...new Set([...items.values()].map(x=>x.rubro))]
   .map(rubro=>({rubro,titulo:RUBROS_MVP216[rubro],
    solicitados:[...items.values()].filter(x=>x.rubro===rubro).length,
    ofertas:byRubro.get(rubro)??0}));
 return {
  received_count:input.recibidos as number,
  files_pending_review:input.pendientes_revision as number,
  offers,rubros_ia:rubros
 };
}

/** MVP216 — rubros en el seguimiento PRIVADO, con trazabilidad.
 * No clasificar precios por palabras de la cotización ni inferir identidad.
 * La familia proviene del pedido protegido por token y su catálogo; en la
 * arquitectura nueva, el rubro será propuesto por IA y persistido en la ronda.
 * Un campo futuro rubro NO habilita publicar un artículo sin fuente revisada.
 */
export const RUBROS_MVP216 = {
 obra_gruesa:'Obra gruesa / Corralón',
 pintura:'Pintura',
 electricidad:'Electricidad',
 construccion_seca:'Construcción en seco',
 sanitarios:'Sanitarios',
 ferreteria:'Ferretería y fijaciones',
 otros:'Otros materiales'
} as const;
export type RubroMvp216=keyof typeof RUBROS_MVP216;
type Item=Readonly<{id:string;familia:string;rubro?:unknown}>;
type PriceItem=Readonly<{itemId:string}>;
export type ResumenRubrosMvp216=Readonly<{
 state:'rubros_por_articulo';items:readonly Readonly<{
  itemId:string;rubro:RubroMvp216
 }>[];
 ranking_allowed:false;contacts_revealed:false;automatic_award:false;
}>;
const IDS=/^item_\d{3}$/u;
const catalogoObra=new Set([
 'cemento_gris_obra','arena_generica','arena_fina','arena_gruesa',
 'piedra_generica','piedra_partida','cal_aerea','cal_hidraulica',
 'ladrillo_comun','ladrillo_hueco','bloque_hormigon','cascote_relleno',
 'hierro_adn','malla_electrosoldada','tosca_relleno','vigueta_pretensada',
 'yeso_obra','revoque_fino','revoque_grueso','hidrofugo'
]);
const catalogoFijaciones=new Set(['alambre_galvanizado',
 'alambre_recocido','clavos_punta_paris']);
function rubroFuente(v:Item):RubroMvp216{
 // Etiqueta IA persistida por el backend, si existe, no inferencia textual.
 if(typeof v.rubro==='string'&&Object.hasOwn(RUBROS_MVP216,v.rubro))
  return v.rubro as RubroMvp216;
 // Compatibilidad con los catálogos LEGACY ya acreditados del piloto.
 if(catalogoObra.has(v.familia))return 'obra_gruesa';
 if(catalogoFijaciones.has(v.familia))return 'ferreteria';
 return 'otros'; // No inventar una clasificación para familias desconocidas.
}
export function resumirRubrosCompradorMvp216(
 status:unknown,privateInput:unknown,itemPrices:unknown
):ResumenRubrosMvp216|null{
 if(!status||typeof status!=='object'||Array.isArray(status)||
    !privateInput||typeof privateInput!=='object'||Array.isArray(privateInput)||
    !itemPrices||typeof itemPrices!=='object'||Array.isArray(itemPrices))
  return null;
 const s=status as Record<string,unknown>;
 const source=privateInput as Record<string,unknown>;
 const prices=itemPrices as Record<string,unknown>;
 if(s.can_open!==true||!['waiting','closed'].includes(String(s.state))||
    source.state!=='private_inputs'||source.rankingAllowed!==false||
    source.contactsRevealed!==false||
    prices.state!=='importes_por_articulo_sin_ranking'||
    prices.ranking_allowed!==false||prices.contacts_revealed!==false||
    !Array.isArray(source.requestItems)||!Array.isArray(prices.articulos)||
    source.requestItems.length<1||source.requestItems.length>30||
    source.requestItems.length!==prices.articulos.length)return null;
 const byId=new Map<string,Item>();
 for(const raw of source.requestItems){
  if(!raw||typeof raw!=='object'||Array.isArray(raw))return null;
  const it=raw as Item;
  if(typeof it.id!=='string'||!IDS.test(it.id)||byId.has(it.id)||
     typeof it.familia!=='string'||it.familia.length<3||
     it.familia.length>80||
     (it.rubro!==undefined&&
      (typeof it.rubro!=='string'||!Object.hasOwn(RUBROS_MVP216,it.rubro))))
   return null;
  byId.set(it.id,it);
 }
 const done=new Set<string>();
 const items:{itemId:string;rubro:RubroMvp216}[]=[];
 for(const raw of prices.articulos){
  if(!raw||typeof raw!=='object'||Array.isArray(raw))return null;
  const id=(raw as PriceItem).itemId;
  const original=byId.get(id);
  if(!original||done.has(id))return null;
  done.add(id);
  items.push(Object.freeze({itemId:id,rubro:rubroFuente(original)}));
 }
 if(done.size!==byId.size)return null;
 return Object.freeze({
  state:'rubros_por_articulo' as const,
  items:Object.freeze(items),
  ranking_allowed:false as const,
  contacts_revealed:false as const,
  automatic_award:false as const
 });
}

/**
 * MVP278 — authenticated binary source -> independent proof -> SQL
 * attestation -> IA Central shadow round. No supplier message or publication.
 *
 * Only the trusted webhook is permitted to invoke the service_role RPC.
 * Original bytes are read by MVP277; a model cannot create an attestation.
 */
import type {DownloadedMedia} from './whapi-media-archive.ts';
import type {DocumentDraft} from './document-ai-draft.ts';
import {
 contrastarDocumentoCompradorMvp277
} from './ai-central-buyer-binary-mvp277.ts';
import {
 procesarCompradorCentralMvp226
} from './ai-central-buyer-mvp226.ts';

type Rpc=(name:string,params:Record<string,unknown>)=>
 Promise<{data:unknown;error:unknown}>;
type Model='gpt-6-luna'|'gpt-6.1-sol';
type State='apagado'|'no_autorizado'|'requiere_revision'|
 'requiere_zona'|'ronda_en_sombra'|'conciliacion_requerida';
type Result=Readonly<{
 estado:State;codigo:string;originalAutorizado:boolean;
 rondaPublicada:false;whatsappEnviado:false;
 contactosRevelados:false;
}>;
const HASH=/^[a-f0-9]{64}$/u;
const mime=new Set([
 'application/pdf',
 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
]);
const finish=(estado:State,codigo:string,verified=false):Result=>Object.freeze({
 estado,codigo,originalAutorizado:verified,
 rondaPublicada:false,whatsappEnviado:false,contactosRevelados:false
});
export async function prepararDocumentoBinarioCompradorMvp278(args:{
 habilitado:boolean;
 autenticadoPorWebhook:boolean;compradorAutorizado:boolean;
 chatHmac:string;messageHmac:string;
 original:DownloadedMedia;primera:DocumentDraft|null;
 segunda:DocumentDraft|null;
 apiKey:string;model:Model;rpc:Rpc;
 contrastar?:typeof contrastarDocumentoCompradorMvp277;
 broker?:typeof procesarCompradorCentralMvp226;
}):Promise<Result>{
 if(args?.habilitado!==true)return finish('apagado','flag_disabled');
 if(!args.autenticadoPorWebhook||!args.compradorAutorizado||
    !HASH.test(args.chatHmac)||!HASH.test(args.messageHmac)||
    !args.original||!mime.has(args.original.mime)||
    !['gpt-6-luna','gpt-6.1-sol'].includes(args.model)||
    typeof args.rpc!=='function')
  return finish('no_autorizado','webhook_or_buyer_not_authorized');
 let checked;
 try{
  checked=await (args.contrastar??contrastarDocumentoCompradorMvp277)({
   habilitado:true,original:args.original,
   primera:args.primera,segunda:args.segunda
  });
 }catch{return finish('requiere_revision','independent_reader_failed')}
 if(checked.estado==='requiere_zona')
  return finish('requiere_zona','locality_not_in_original');
 if(checked.estado!=='fuente_contrastada_privada'||
    checked.origenIndependiente!==true||
    checked.rondaCreada!==false||checked.whatsappEnviado!==false||
    checked.soloVistaPrivada!==true||
    !HASH.test(checked.sha256Original??'')||
    !HASH.test(checked.sha256TextoDerivado??'')||
    checked.sha256Original!==args.original.sha256||
    !Number.isInteger(checked.renglonesAcreditados)||
    checked.renglonesAcreditados<1||checked.renglonesAcreditados>25||
    typeof checked.textoFuentePrivado!=='string'||
    checked.textoFuentePrivado.length<10||
    checked.textoFuentePrivado.length>4000)
  return finish('requiere_revision','binary_source_not_proven');
 const derived=checked.textoFuentePrivado;
 let attested;
 try{
  attested=await args.rpc('cotironda_piloto_ia_attest_binary_mvp278',{
   p_chat_hmac:args.chatHmac,
   p_message_hmac:args.messageHmac,
   p_original_sha256:checked.sha256Original,
   p_derived_text:derived,
   p_mime:args.original.mime,
   p_verified_items:checked.renglonesAcreditados
  });
 }catch{
  // An ambiguous RPC response may mean the attestation committed.
  // Do not retry a financial workflow after a network failure.
  return finish('conciliacion_requerida','attestation_uncertain');
 }
 if(attested.error!==null&&attested.error!==undefined)
  return finish('conciliacion_requerida','attestation_uncertain');
 const data=attested.data;
 const state=(data&&typeof data==='object'&&!Array.isArray(data))?
  (data as Record<string,unknown>).state:null;
 if(state!=='attested'&&state!=='already_attested')
  return finish('requiere_revision','sql_original_not_authorized');
 try{
  const broker=await (args.broker??procesarCompradorCentralMvp226)({
   habilitado:true,
   // No buyer-signed review confirmation yet. NEVER publish a binary
   // document from automatic webhook processing on this bridge.
   publicar:false,
   autenticadoPorWebhook:true,
   chatHmac:args.chatHmac,messageHmac:args.messageHmac,
   fuente:derived,sourceSha256:checked.sha256TextoDerivado!,
   apiKey:args.apiKey,model:args.model,rpc:args.rpc
  });
  if(broker.whatsappEnviado!==false||
     broker.estado==='ronda_publicada')
   return finish('conciliacion_requerida','unexpected_publication',true);
  if(broker.estado==='ronda_en_sombra')
   return finish('ronda_en_sombra','verified_source_staged',true);
  if(broker.estado==='requiere_zona')
   return finish('requiere_zona','delivery_city_missing',true);
  if(broker.estado==='conciliacion_requerida')
   return finish('conciliacion_requerida','broker_uncertain',true);
  return finish('requiere_revision','semantic_or_catalogue_review',true);
 }catch{
  return finish('conciliacion_requerida','broker_uncertain',true);
 }
}

/**
 * MVP277 — independent, PRIVATE buyer document source check.
 *
 * Accepts only PDF with embedded positioned text, or simple DOCX/XLSX that
 * the existing strict ZIP/XML readers can decode in full.
 * This DOES NOT authorize a round: SQL MVP276 only supports TXT/CSV bytes.
 * Two identical model readings cannot replace independent binary evidence.
 */
import type {DocumentDraft} from './document-ai-draft.ts';
import type {DownloadedMedia} from './whapi-media-archive.ts';
import {readOfficeVisibleRows} from './supplier-source-office.ts';
import {
 readPdfPositioned,type PdfSourceEvidence
} from './supplier-source-pdf-general.ts';

const PDF='application/pdf';
const DOCX='application/vnd.openxmlformats-officedocument.wordprocessingml.document';
const XLSX='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
const SUPPORTED=new Set([PDF,DOCX,XLSX]);
const HEX=/^[a-f0-9]{64}$/u;
const CTRL=/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/u;
const DECIMAL=/^(?:0|[1-9][0-9]{0,5})(?:[.,][0-9]{1,3})?$/u;
const HEADING=/^(?:pedido|lista|solicitud|materiales|rubro|obra|entrega|destino|zona|localidad|direcci[oó]n|ubicaci[oó]n|cantidad|unidad|descripci[oó]n|detalle)(?:\b|[:\s])/iu;
type State='apagado'|'requiere_revision'|'requiere_zona'|'fuente_contrastada_privada';
export type AtestacionDocumentalCompradorMvp277=Readonly<{
 estado:State;codigo:string;
 sha256Original:string|null;sha256TextoDerivado:string|null;
 renglonesAcreditados:number;origenIndependiente:boolean;
 soloVistaPrivada:true;rondaCreada:false;whatsappEnviado:false;
 // Only in trusted server memory. Never include this in an HTTP response/log.
 textoFuentePrivado:string|null;
}>;
const result=(estado:State,codigo:string,hash:string|null=null,
 textHash:string|null=null,rows=0,text:string|null=null):
 AtestacionDocumentalCompradorMvp277=>Object.freeze({
 estado,codigo,sha256Original:hash,sha256TextoDerivado:textHash,
 renglonesAcreditados:rows,origenIndependiente:estado==='fuente_contrastada_privada',
 soloVistaPrivada:true,rondaCreada:false,whatsappEnviado:false,
 textoFuentePrivado:text
});
const hex=(b:Uint8Array):string=>Array.from(b,x=>x.toString(16).padStart(2,'0')).join('');
const sha=async(bytes:Uint8Array):Promise<string>=>hex(
 new Uint8Array(await crypto.subtle.digest('SHA-256',Uint8Array.from(bytes)))
);
const normalize=(x:string):string=>x.normalize('NFKC')
 .replace(/\s+/gu,' ').trim().toLocaleLowerCase('es-AR');
const token=(s:string,value:string,forQuantity=false):boolean=>{
 const source=normalize(s),needle=normalize(value);
 if(!needle)return false;
 let i=source.indexOf(needle);
 while(i>=0){
  const left=source.slice(0,i),right=source.slice(i+needle.length);
  const boundary=forQuantity?/[\p{L}\p{N}.,]/u:/[\p{L}\p{N}]/u;
  if(!boundary.test(left.slice(-1))&&!boundary.test(right.slice(0,1)))
   return true;
  i=source.indexOf(needle,i+1);
 }
 return false;
};
const stripToken=(source:string,tokenValue:string,quantity=false):string|null=>{
 const lower=normalize(source),needle=normalize(tokenValue);
 let i=lower.indexOf(needle);
 while(i>=0){
  const before=lower.slice(0,i),after=lower.slice(i+needle.length);
  const boundary=quantity?/[\p{L}\p{N}.,]/u:/[\p{L}\p{N}]/u;
  if(!boundary.test(before.slice(-1))&&!boundary.test(after.slice(0,1)))
   return before+' '+after;
  i=lower.indexOf(needle,i+1);
 }
 return null;
};
const signature=(d:DocumentDraft)=>JSON.stringify({
 status:d.status,kind:d.kind,city:d.delivery_city,note:d.requested_delivery_note,
 total:d.total_declared,unanswered:d.unanswered,
 lines:d.lines.map(l=>[
  l.original_description,l.quantity,l.unit,l.unit_price,l.line_total,l.ambiguity
 ])
});
const credible=(d:DocumentDraft|null):d is DocumentDraft=>
 !!d&&d.kind==='buyer_request'&&d.status==='review_required'&&
 Array.isArray(d.lines)&&d.lines.length>0&&d.lines.length<=25&&
 Array.isArray(d.unanswered)&&d.unanswered.length===0&&
 d.total_declared===null&&
 (d.delivery_city===null||typeof d.delivery_city==='string'&&
  d.delivery_city.trim().length>=3&&d.delivery_city.length<=80)&&
 d.lines.every(l=>l&&typeof l.original_description==='string'&&
  l.original_description.trim().length>=3&&l.original_description.length<=500&&
  typeof l.quantity==='string'&&DECIMAL.test(l.quantity)&&
  typeof l.unit==='string'&&l.unit.trim().length>0&&l.unit.length<=40&&
  l.ambiguity===null&&l.unit_price===null&&l.line_total===null&&
  typeof l.evidence_location==='string'&&l.evidence_location.trim().length>0);
export async function contrastarDocumentoCompradorMvp277(args:{
 habilitado:boolean;
 original:DownloadedMedia;
 primera:DocumentDraft|null;
 segunda:DocumentDraft|null;
 // Inject only in tests. Production uses the actual strict source readers.
 lectorPdf?:typeof readPdfPositioned;
 lectorOffice?:typeof readOfficeVisibleRows;
}):Promise<AtestacionDocumentalCompradorMvp277>{
 if(args?.habilitado!==true)return result('apagado','flag_disabled');
 const input=args.original;
 if(!input||!SUPPORTED.has(input.mime)||!HEX.test(input.sha256)||
    !(input.bytes instanceof Uint8Array)||
    input.bytes.length<120||input.bytes.length>3145728)
  return result('requiere_revision','source_format_or_size_invalid');
 let actual:string;
 try{actual=await sha(input.bytes)}catch{
  return result('requiere_revision','hash_unavailable');
 }
 if(actual!==input.sha256)
